let renderSeq = 0;

function MetricWidget({ metricId, range }: { metricId: string; range: string }) {
  // tag every render so the backend can correlate logs
  renderSeq += 1;
  logImpression(metricId, renderSeq);

  const [data, setData] = useState<Point[] | null>(null);
  const labelRef = useRef<string>("");
  labelRef.current = `${metricId} (${range})`;

  useEffect(() => {
    const controller = new AbortController();
    fetchMetric(metricId, range, controller.signal).then(setData);
    return () => controller.abort();
  }, [metricId, range]);

  const formatted = data?.map((p) => ({ ...p, label: fmt(p.t) }));

  return (
    <section aria-label={labelRef.current}>
      <h3>{labelRef.current}</h3>
      <Chart points={formatted ?? []} />
    </section>
  );
}
